const raw = $input.first().json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const str = (v, fallback = '') => (v === undefined || v === null || v === '' ? fallback : String(v));
const num = (v, fallback = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

return [{
  json: {
    event_id: str(body.event_id || raw.event_id, 'evt_unknown_' + Date.now()),
    transaction_id: str(body.transaction_id || raw.transaction_id, 'txn_unknown'),
    customer_id: str(body.customer_id || raw.customer_id, 'cus_unknown'),
    customer_email: str(body.customer_email || raw.customer_email, ''),
    amount: num(body.amount ?? raw.amount, 0),
    currency: str(body.currency || raw.currency, 'USD').toUpperCase(),
    payment_provider: str(body.payment_provider || raw.payment_provider, 'unknown'),
    failure_code: str(body.failure_code || raw.failure_code, 'unknown'),
    failure_reason: str(body.failure_reason || raw.failure_reason, 'unknown'),
    failure_message: str(body.failure_message || raw.failure_message, 'Payment failed'),
    payment_id: str(body.payment_id || raw.payment_id, ''),
    failed_at: str(body.failed_at || raw.failed_at, new Date().toISOString())
  }
}];

const payment = $('Clean Up Payment Details').first().json;
const lookup = $input.first().json || {};

// Lookup returns a row when event_id already exists in RetryQueue
const lookupEventId = lookup.event_id != null ? String(lookup.event_id) : '';
const paymentEventId = payment.event_id != null ? String(payment.event_id) : '';
const isDuplicate = !!(lookupEventId && paymentEventId && lookupEventId === paymentEventId);

return [{
  json: {
    ...payment,
    is_duplicate: isDuplicate,
    existing_record_id: lookup.id || null
  }
}];

const now = Date.now();
const blocked = new Set(['SUCCESS', 'CUSTOMER_ACTION_REQUIRED', 'MAX_RETRIES_REACHED', 'CANCELLED']);
const items = $input.all();
const due = [];

for (const item of items) {
  const row = item.json || {};
  const status = String(row.status || '').toUpperCase().trim();
  if (blocked.has(status)) continue;
  if (status !== 'SCHEDULED') continue;

  const retryCount = Number(row.retry_count || 0);
  const maxRetries = Number(row.max_retries || 0);
  if (!(retryCount < maxRetries)) continue;

  const nextRaw = row.next_retry_at;
  if (!nextRaw) continue;
  const nextMs = new Date(nextRaw).getTime();
  if (Number.isNaN(nextMs) || nextMs > now) continue;

  due.push({ json: { ...row, retry_count: retryCount, max_retries: maxRetries } });
}

return due;

const record = $('Process One Payment at a Time').item.json;
const resp = $input.first().json || {};

// Support fullResponse and plain body shapes
const statusCode = Number(
  resp.statusCode ??
  resp.status ??
  (resp.headers && resp.statusCode) ??
  0
);

const body = (resp.body !== undefined)
  ? (typeof resp.body === 'string' ? (() => { try { return JSON.parse(resp.body); } catch { return { raw: resp.body }; } })() : resp.body)
  : resp;

const paymentStatus = String(
  body.status ||
  body.payment_status ||
  body.paymentStatus ||
  body.result ||
  ''
).toLowerCase();

const httpOk = statusCode >= 200 && statusCode < 300;
const statusOk = ['succeeded', 'success', 'paid', 'completed', 'ok'].includes(paymentStatus);
// If provider returns 2xx with explicit success flag, accept; if 2xx and no status field, treat as success when body.success === true
const flagOk = body.success === true || body.paid === true;
const paymentSuccessful = httpOk && (statusOk || flagOk || (paymentStatus === '' && httpOk && body.error == null && !body.failure_code));

const errorMessage = body.failure_message || body.message || body.error || body.last_error || (paymentSuccessful ? '' : `HTTP ${statusCode || 'error'}`);
const failureReason = String(
  body.failure_reason ||
  body.decline_code ||
  record.failure_reason ||
  'processor_error'
).toLowerCase().replace(/\s+/g, '_');

return [{
  json: {
    ...record,
    http_status_code: statusCode,
    payment_response_status: paymentStatus,
    payment_successful: paymentSuccessful,
    last_error: String(errorMessage || '').slice(0, 500),
    failure_reason: failureReason,
    retry_response: body
  }
}];

const input = $input.first().json || {};

const RULES = {
  insufficient_funds: 72,
  processor_error: 2,
  network_error: 1,
  timeout: 1
};

const reason = String(input.failure_reason || 'processor_error').toLowerCase().replace(/\s+/g, '_');
const delayHours = RULES[reason] != null ? RULES[reason] : 24; // conservative default if still retryable path

const prevCount = Number(input.retry_count || 0);
const maxRetries = Number(input.max_retries || 0);
const newCount = prevCount + 1;
const nowIso = new Date().toISOString();

const canRetryAgain = newCount < maxRetries;

let next_retry_at = '';
let status = 'MAX_RETRIES_REACHED';
let retry_again = false;

if (canRetryAgain) {
  next_retry_at = new Date(Date.now() + delayHours * 60 * 60 * 1000).toISOString();
  status = 'SCHEDULED';
  retry_again = true;
}

return [{
  json: {
    ...input,
    retry_count: newCount,
    retry_delay_hours: delayHours,
    next_retry_at,
    last_retry_at: nowIso,
    updated_at: nowIso,
    status,
    retry_again,
    customer_action_required: false
  }
}];

const input = $input.first().json || {};

const reasonRaw = String(input.failure_reason || input.failure_code || 'unknown').toLowerCase().trim();
const reason = reasonRaw.replace(/\s+/g, '_');

const RULES = {
  insufficient_funds: { action: 'RETRY', delayHours: 72, maxRetries: 3 },
  processor_error: { action: 'RETRY', delayHours: 2, maxRetries: 3 },
  network_error: { action: 'RETRY', delayHours: 1, maxRetries: 3 },
  timeout: { action: 'RETRY', delayHours: 1, maxRetries: 3 },
  expired_card: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 },
  invalid_card: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 },
  authentication_required: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 },
  fraud: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 },
  do_not_honor: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 },
  stolen_card: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 },
  lost_card: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 },
  pickup_card: { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 }
};

// Safe default for unknown / high-risk: require customer action (no aggressive auto-retry)
const rule = RULES[reason] || { action: 'CUSTOMER_ACTION', delayHours: 0, maxRetries: 0 };

const failedAt = input.failed_at ? new Date(input.failed_at) : new Date();
const baseMs = Number.isNaN(failedAt.getTime()) ? Date.now() : failedAt.getTime();
const nowIso = new Date().toISOString();

let result;
if (rule.action === 'RETRY') {
  const nextRetryAt = new Date(baseMs + rule.delayHours * 60 * 60 * 1000).toISOString();
  result = {
    retry_action: 'RETRY',
    retry_delay_hours: rule.delayHours,
    next_retry_at: nextRetryAt,
    retry_count: 0,
    max_retries: rule.maxRetries,
    customer_action_required: false,
    status: 'SCHEDULED'
  };
} else {
  result = {
    retry_action: 'CUSTOMER_ACTION',
    retry_delay_hours: 0,
    next_retry_at: '',
    retry_count: 0,
    max_retries: 0,
    customer_action_required: true,
    status: 'CUSTOMER_ACTION_REQUIRED'
  };
}

const recordId = 'retry_' + String(input.event_id || 'unknown') + '_' + Date.now();

return [{
  json: {
    ...input,
    failure_reason_normalized: reason,
    ...result,
    id: recordId,
    original_failed_at: input.failed_at || nowIso,
    last_retry_at: '',
    last_error: input.failure_message || '',
    created_at: nowIso,
    updated_at: nowIso
  }
}];
